import{_ as d,c as e,o,at as r}from"./chunks/framework.mXguc-v6.js";const h=JSON.parse('{"title":"Vue 2 vs Vue 3 核心差异","description":"","frontmatter":{},"headers":[],"relativePath":"views/interview/frontend/vue/versions.md","filePath":"views/interview/frontend/vue/versions.md","lastUpdated":null}'),a={name:"views/interview/frontend/vue/versions.md"};function n(s,t,c,i,l,p){return o(),e("div",null,t[0]||(t[0]=[r(`<h1 id="vue-2-vs-vue-3-核心差异" tabindex="-1">Vue 2 vs Vue 3 核心差异 <a class="header-anchor" href="#vue-2-vs-vue-3-核心差异" aria-label="Permalink to &quot;Vue 2 vs Vue 3 核心差异&quot;">​</a></h1><h2 id="一、创建应用" tabindex="-1">一、创建应用 <a class="header-anchor" href="#一、创建应用" aria-label="Permalink to &quot;一、创建应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>实例化</td><td><code>new Vue({ el: &#39;#app&#39; })</code></td><td><code>createApp(App).mount(&#39;#app&#39;)</code></td></tr><tr><td>多实例</td><td>一个页面只能一个 Vue 实例</td><td>支持多个应用实例共存</td></tr><tr><td>全局 API</td><td><code>Vue.mixin()</code> / <code>Vue.directive()</code></td><td><code>app.mixin()</code> / <code>app.directive()</code> — 按应用隔离</td></tr></tbody></table><h2 id="二、响应式系统" tabindex="-1">二、响应式系统 <a class="header-anchor" href="#二、响应式系统" aria-label="Permalink to &quot;二、响应式系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>核心</td><td><code>Object.defineProperty</code></td><td><code>Proxy</code></td></tr><tr><td>新增属性</td><td>❌ 检测不到，需 <code>Vue.set()</code></td><td>✅ 自动追踪</td></tr><tr><td>删除属性</td><td>❌ 检测不到，需 <code>Vue.delete()</code></td><td>✅ 自动追踪</td></tr><tr><td>数组下标</td><td>❌ 检测不到，需 <code>splice()</code></td><td>✅ 原生支持</td></tr><tr><td>初始化开销</td><td>递归遍历所有属性</td><td>懒代理（访问到才代理）</td></tr><tr><td>Set/Map</td><td>❌ 不支持</td><td>✅ 支持</td></tr><tr><td>多个响应式副本</td><td>—</td><td><code>ref</code> / <code>reactive</code> / <code>shallowRef</code> / <code>shallowReactive</code></td></tr></tbody></table><h2 id="三、api-风格" tabindex="-1">三、API 风格 <a class="header-anchor" href="#三、api-风格" aria-label="Permalink to &quot;三、API 风格&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>默认</td><td>Options API</td><td>Options API + Composition API</td></tr><tr><td>逻辑复用</td><td>mixins（命名冲突、来源不清）</td><td>composables（无冲突，来源明确）</td></tr><tr><td>setup()</td><td>❌</td><td>✅</td></tr><tr><td><code>&lt;script setup&gt;</code></td><td>❌</td><td>✅（3.2+）</td></tr><tr><td>TypeScript</td><td>勉强支持（装饰器方案）</td><td>一流支持</td></tr></tbody></table><h2 id="四、生命周期对照" tabindex="-1">四、生命周期对照 <a class="header-anchor" href="#四、生命周期对照" aria-label="Permalink to &quot;四、生命周期对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vue 2</th><th>Vue 3 Options</th><th>Vue 3 Composition</th></tr></thead><tbody><tr><td><code>beforeCreate</code></td><td><code>beforeCreate</code></td><td><code>setup()</code></td></tr><tr><td><code>created</code></td><td><code>created</code></td><td><code>setup()</code></td></tr><tr><td><code>beforeMount</code></td><td><code>beforeMount</code></td><td><code>onBeforeMount</code></td></tr><tr><td><code>mounted</code></td><td><code>mounted</code></td><td><code>onMounted</code></td></tr><tr><td><code>beforeUpdate</code></td><td><code>beforeUpdate</code></td><td><code>onBeforeUpdate</code></td></tr><tr><td><code>updated</code></td><td><code>updated</code></td><td><code>onUpdated</code></td></tr><tr><td><code>beforeDestroy</code></td><td><code>beforeUnmount</code></td><td><code>onBeforeUnmount</code></td></tr><tr><td><code>destroyed</code></td><td><code>unmounted</code></td><td><code>onUnmounted</code></td></tr><tr><td><code>errorCaptured</code></td><td><code>errorCaptured</code></td><td><code>onErrorCaptured</code></td></tr><tr><td>—</td><td><code>renderTracked</code>（开发）</td><td><code>onRenderTracked</code></td></tr><tr><td>—</td><td><code>renderTriggered</code>（开发）</td><td><code>onRenderTriggered</code></td></tr></tbody></table><blockquote><p>Vue 3 重命名了销毁相关的生命周期，语义更清晰。</p></blockquote><h2 id="五、组件通信" tabindex="-1">五、组件通信 <a class="header-anchor" href="#五、组件通信" aria-label="Permalink to &quot;五、组件通信&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>props + emit</td><td>✅</td><td>✅（支持 <code>defineEmits</code> 类型声明）</td></tr><tr><td>v-model</td><td>一个组件只能一个 <code>.sync</code> 修饰符</td><td>支持多个 <code>v-model:xxx</code></td></tr><tr><td>provide / inject</td><td>✅ 非响应式</td><td>✅ 可通过 <code>ref</code>/<code>reactive</code> 传递响应式数据</td></tr><tr><td>event bus</td><td><code>new Vue()</code> 实例做总线</td><td>推荐 <code>mitt</code> 库（3KB）</td></tr><tr><td>$attrs</td><td>包含 class/style</td><td>默认不包含 class/style（inheritAttrs 控制）</td></tr><tr><td>$listeners</td><td>独立存在</td><td>合并到 <code>$attrs</code></td></tr></tbody></table><h2 id="六、渲染与模板" tabindex="-1">六、渲染与模板 <a class="header-anchor" href="#六、渲染与模板" aria-label="Permalink to &quot;六、渲染与模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>根元素</td><td>必须<strong>一个</strong>根节点</td><td>支持<strong>多个</strong>根节点（Fragment）</td></tr><tr><td>Teleport</td><td>❌</td><td>✅ <code>&lt;Teleport to=&quot;body&quot;&gt;</code></td></tr><tr><td>Suspense</td><td>❌</td><td>✅（实验性 → 稳定）</td></tr><tr><td>v-memo</td><td>❌</td><td>✅（3.2+，条件跳过渲染）</td></tr><tr><td>静态提升</td><td>❌</td><td>✅ 编译时优化</td></tr><tr><td>PatchFlags</td><td>❌</td><td>✅ 标记动态节点</td></tr><tr><td>Block Tree</td><td>❌</td><td>✅ 摊平模板追踪</td></tr><tr><td>v-if 优先级</td><td>比 v-for 低</td><td>比 v-for 高⚠️</td></tr><tr><td><code>key</code> 在 template</td><td>❌</td><td>✅</td></tr></tbody></table><h2 id="七、生态与工具" tabindex="-1">七、生态与工具 <a class="header-anchor" href="#七、生态与工具" aria-label="Permalink to &quot;七、生态与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>路由</td><td>vue-router 3</td><td>vue-router 4</td></tr><tr><td>状态管理</td><td>Vuex 3/4</td><td>Pinia（推荐，替代 Vuex）</td></tr><tr><td>构建工具</td><td>Vue CLI (Webpack)</td><td>Vite（默认）</td></tr><tr><td>DevTools</td><td>Vue Devtools 6</td><td>Vue Devtools 7</td></tr><tr><td>脚手架</td><td><code>vue init</code></td><td><code>create-vue</code></td></tr><tr><td>组件库</td><td>Element UI / Vant 2</td><td>Element Plus / Vant 4</td></tr><tr><td>服务端渲染</td><td>Nuxt 2</td><td>Nuxt 3</td></tr><tr><td>测试</td><td>Jest + @vue/test-utils 1</td><td>Vitest + @vue/test-utils 2</td></tr></tbody></table><h2 id="八、升级路径要点" tabindex="-1">八、升级路径要点 <a class="header-anchor" href="#八、升级路径要点" aria-label="Permalink to &quot;八、升级路径要点&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 生命周期：beforeDestroy → beforeUnmount, destroyed → unmounted</span></span>
<span class="line"><span>2. 全局 API：Vue.mixin() → app.mixin()（按应用隔离）</span></span>
<span class="line"><span>3. v-model：.sync 改为多个 v-model:xxx</span></span>
<span class="line"><span>4. 过滤器（filters）：删除，改用 computed/methods</span></span>
<span class="line"><span>5. 事件 API：$on/$off 删除（event bus 用 mitt）</span></span>
<span class="line"><span>6. v-if/v-for 优先级：反过来（3 中 v-if 优先级更高）</span></span>
<span class="line"><span>7. 异步组件：Vue.component() → defineAsyncComponent()</span></span>
<span class="line"><span>8. 函数式组件：functional: true 删除，函数组件就是普通函数</span></span>
<span class="line"><span>9. key 在 template 可用</span></span>
<span class="line"><span>10. \`$listeners\` 合并到 \`$attrs\`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div>`,18)]))}const b=d(a,[["render",n]]);export{h as __pageData,b as default};
